    fetch: async (path) => {
      requests++;
      const result = path.endsWith('/tasks')
        ? [{ id: 1, title: 'Open task', completed: false }, { id: 2, title: 'Done task', completed: true }]
        : { id: 1, name: 'Archived', archived: true };
      return { ok: true, json: async () => result };
    },
  });
